/* 第08轮：关系总览与可读镜头工作区，复用导演表单及版本规则。 */
(()=>{
 const C=Cimora,{S,M,E}=C;createCimoraFocusModel(M,S);const F=M.focus,D=M.direction;
 const B=(text,action,id='',extra='')=>`<button type="button" class="cm-button ghost" data-focus="${action}" data-id="${E(id)}" ${extra}>${text}</button>`;
 function source(c,s){const refs=s.direction.references;return `<details class="fc-relations cm-panel"><summary>漫画来源 ${s.sources?.length||0} · 已选用途参考 ${refs.length}</summary><p>来源关系与用途参考独立；前后镜按钮仅按故事叙事顺序切换，不改剪辑顺序。</p><div class="fc-rel-grid">${(s.sources||[]).map(r=>`<article><b>漫画来源 · ${E(r.snapshot.title)} · v${r.version}</b>${C.comicBaseImage(r.snapshot)}${C.comicSourceDetails(r.snapshot)}<p>${E(r.snapshot.action||'')}</p></article>`).join('')||'<p>独立镜头，没有漫画来源。</p>'}${refs.map(r=>`<article><b>用途：${E(D.purposes[r.purpose]||r.purpose)} · 固定v${r.version}</b>${r.kind==='source'?C.comicBaseImage(r.snapshot):C.art(r.snapshot.art||0,r.snapshot.name)}<p>${E(r.snapshot.name||r.snapshot.title)}</p></article>`).join('')||'<p>未选用途参考；不会发送全项目素材。</p>'}</div></details>`;}
 function focus(c){const f=F.state(c),s=F.current(c);if(!s){F.back(c);return '<p>当前没有可聚焦镜头，请返回镜头方案。</p>';}c.e.selectedShotId=s.id;const ss=D.ensure(c),i=ss.indexOf(s),doc=new DOMParser().parseFromString(C.productionMotion(c),'text/html'),work=doc.querySelector('.di-workbench'),main=work.querySelector('.di-main'),preview=main.children[0],editor=main.children[1],cards=work.querySelector('.di-candidates'),candidate=F.compared(c),used=s.candidates.find(v=>v.id===s.adoptedId);
 // 只在需要时展开详细输入；不把全历史或其他镜头塞进主工作区。
 const extras=[...work.children].filter(el=>el.matches('details.cm-panel')&&!el.textContent.includes('范围生成')&&!el.textContent.includes('前后镜头状态'));
 const candidateCard=v=>v?[...cards.children].find(el=>el.querySelector('[data-candidate]')?.dataset.candidate===v.id)?.outerHTML||'<p>该候选无可展示记录。</p>':'<p class="fc-empty">尚无候选。返回镜头创作，确认生成后再比较。</p>';
 const usedCard=used?candidateCard(used):'<article><h3>尚未采用</h3><p>生成候选后须显式采用；最新候选不会自动成为采用版。</p></article>';
 const compare=`<section class="fc-compare"><div class="fc-compare-heading"><div><h3>采用版与所选候选</h3><p>左侧固定当前采用；右侧明确选择。比较不改变采用记录。</p></div><label>选择比较候选<select aria-label="选择比较候选" data-focus-candidate>${s.candidates.map(v=>`<option value="${v.id}" ${candidate?.id===v.id?'selected':''}>v${v.version} · ${v.id===s.adoptedId?'当前采用':v.status==='failed'?'失败':'待采用'}</option>`).join('')}</select></label></div><div class="di-candidates fc-compare-grid"><section><h3>当前采用 ${used?'v'+used.version:'无'}</h3>${usedCard}</section><section><h3>所选候选 ${candidate?'v'+candidate.version:'无'}</h3>${candidateCard(candidate)}</section></div>${s.candidates.length>2?`<details><summary>其余候选历史摘要 · ${s.candidates.length}版</summary>${s.candidates.map(v=>`<p>v${v.version} · ${E(v.input.intent)} ${B('比较此版','candidate',v.id)}</p>`).join('')}</details>`:''}</section>`;
 return `<section class="fc-shell"><header class="fc-toolbar"><div><small>当前镜头聚焦 · 叙事镜头 ${i+1}/${ss.length}</small><h2>${E(s.title)} <span>${s.direction.locked?'已锁定':used?'采用v'+used.version:'尚未采用'}${s.direction.adoption?.mode==='automatic-review'?' · 自动初稿待审阅':''}</span></h2></div><div>${B('← 前镜','prev','',i===0?'disabled':'')}${B('后镜 →','next','',i===ss.length-1?'disabled':'')}${B('返回总览','back')}</div></header><nav class="fc-tabs" aria-label="镜头聚焦任务">${B('镜头创作','work','',f.tab!=='compare'?'aria-current="true"':'')}${B('比较与采用 · '+s.candidates.length+'版','compare','',f.tab==='compare'?'aria-current="true"':'')}</nav><div class="fc-body">${f.tab==='compare'?compare:`<div class="fc-main di-main">${preview.outerHTML}${editor.outerHTML}</div>${source(c,s)}<div class="fc-details">${extras.map(el=>el.outerHTML).join('')}</div>`}</div></section>`;
 }
 const oldCanvas=C.canvas;C.canvas=c=>{if(c.c.kind!=='episode'||c.e.creationCanvas?.legacy)return oldCanvas(c);if(F.state(c).active){const f=F.state(c);if(f.shotId!==c.e.selectedShotId){f.shotId=c.e.selectedShotId;f.candidateId=null;}return focus(c);}const doc=new DOMParser().parseFromString(oldCanvas(c),'text/html');doc.querySelector('.bc-inspector')?.remove();const s=D.shot(c,c.e.selectedShotId)||D.ensure(c)[0],bar=doc.querySelector('.bc-toolbar');if(s)bar?.insertAdjacentHTML('beforeend',B('聚焦当前镜头','open',s.id));doc.querySelector('.bc-shell')?.classList.add('fc-overview');if(s)doc.querySelector('.bc-groups')?.insertAdjacentHTML('afterend',`<div class="fc-selection"><b>当前选择：镜头${D.ensure(c).indexOf(s)+1} · ${E(s.title)}</b><span>${s.direction.locked?'已锁定 · ':''}${s.adoptedId?'采用v'+s.candidates.find(v=>v.id===s.adoptedId)?.version:'未采用'} · ${s.candidates.length}候选</span><small>总览用于关系定位；进入聚焦可按原尺寸编辑与比较。</small>${B('聚焦此镜头 →','open',s.id)}</div>`);return doc.body.innerHTML;};
 window.addEventListener('click',ev=>{const c=C.ctx();if(c?.c.kind!=='episode'||c.e.view!=='canvas')return;const el=ev.target.closest('[data-focus]'),direct=ev.target.closest('[data-direct="select"],[data-direct="step"][data-step="compare"]');if(!el&&!direct)return;ev.preventDefault();ev.stopImmediatePropagation();if(direct){if(direct.dataset.direct==='select')F.open(c,direct.dataset.id);else F.compare(c);}else switch(el.dataset.focus){case'open':F.open(c,el.dataset.id);break;case'prev':F.step(c,-1);break;case'next':F.step(c,1);break;case'back':F.back(c);break;case'compare':F.compare(c);break;case'candidate':F.compare(c,el.dataset.id);break;case'work':F.state(c).tab='work';M.save();break;}S.render();},true);
 window.addEventListener('change',ev=>{if(!ev.target.matches('[data-focus-candidate]'))return;F.compare(C.ctx(),ev.target.value);S.render();},true);
 // 流程切回画布时沿用当前镜头；在聚焦内切镜不动总览位置。
 const oldAfter=C.afterRender;C.afterRender=r=>{const c=C.ctx();if(c?.c.kind==='episode'&&c.e.view==='canvas'&&c.e.canvasFocus?.active&&c.e.canvasFocus.shotId!==c.e.selectedShotId){c.e.canvasFocus.shotId=c.e.selectedShotId;c.e.canvasFocus.candidateId=null;}oldAfter(r);};
})();

